import sys
import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n <= 0:
        return
    numbers = list(map(int, data[1:n+1]))
    primes = [x for x in numbers if is_prime(x)]
    primes.sort(reverse=True)
    for p in primes:
        print(p)

if __name__ == "__main__":
    main()
